{"name": "create_theme_analyst_role", "query": "
-- ============================================================
-- STEP 1: CREATE THE theme_analyst ROLE
-- ============================================================
-- Drop role if it already exists (idempotent)
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT FROM pg_catalog.pg_roles WHERE rolname = 'theme_analyst'
  ) THEN
    CREATE ROLE theme_analyst;
  END IF;
END
$$;

-- ============================================================
-- STEP 2: GRANT SELECT ON REFERENCE TABLES
-- These tables are read-only lookup/reference data
-- ============================================================
GRANT SELECT ON public.lego_themes         TO theme_analyst;
GRANT SELECT ON public.lego_colors         TO theme_analyst;
GRANT SELECT ON public.lego_parts          TO theme_analyst;
GRANT SELECT ON public.lego_part_categories TO theme_analyst;

-- ============================================================
-- STEP 3: GRANT SELECT ON MAIN DATA TABLES
-- These tables will be filtered by RLS policies
-- ============================================================
GRANT SELECT ON public.lego_sets           TO theme_analyst;
GRANT SELECT ON public.lego_inventories    TO theme_analyst;
GRANT SELECT ON public.lego_inventory_parts TO theme_analyst;

-- ============================================================
-- STEP 4: EXPLICITLY REVOKE INSERT/UPDATE/DELETE
-- (these are not granted by default, but we make it explicit)
-- ============================================================
REVOKE INSERT, UPDATE, DELETE ON public.lego_themes          FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON public.lego_colors          FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON public.lego_parts           FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON public.lego_part_categories FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON public.lego_sets            FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON public.lego_inventories     FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON public.lego_inventory_parts FROM theme_analyst;
"}

