{"query": "
-- ============================================================
-- Test 6: Write prevention — INSERT/UPDATE/DELETE must fail
-- ============================================================
SET LOCAL ROLE theme_analyst;

DO $$
DECLARE
  insert_blocked BOOLEAN := FALSE;
  update_blocked BOOLEAN := FALSE;
  delete_blocked BOOLEAN := FALSE;
BEGIN
  -- Test INSERT blocked
  BEGIN
    INSERT INTO public.lego_sets(set_num, name, year, theme_id, num_parts)
    VALUES ('TEST-HACK', 'Security Test', 2024, 18, 0);
  EXCEPTION WHEN OTHERS THEN
    insert_blocked := TRUE;
  END;

  -- Test UPDATE blocked
  BEGIN
    UPDATE public.lego_sets SET name = 'Hacked!' WHERE theme_id = 18;
  EXCEPTION WHEN OTHERS THEN
    update_blocked := TRUE;
  END;

  -- Test DELETE blocked
  BEGIN
    DELETE FROM public.lego_sets WHERE theme_id = 18;
  EXCEPTION WHEN OTHERS THEN
    delete_blocked := TRUE;
  END;

  RAISE NOTICE 'INSERT blocked: %, UPDATE blocked: %, DELETE blocked: %',
    insert_blocked, update_blocked, delete_blocked;
END;
$$;
"}
